<?php
$base = 'http://127.0.0.1:8090'; $users = array( 'cdc_admin', 'cdc_member' ); $urls = array( '/mon-espace/', '/wp-admin/', '/wp-admin/profile.php', '/wp-admin/index.php', '/wp-login.php' ); $pass = 'RC4-local-only-password!';
function login_cookie( string $base, string $login, string $pass ): array { $post = http_build_query( array( 'log' => $login, 'pwd' => $pass, 'wp-submit' => 'Log In', 'redirect_to' => $base . '/mon-espace/', 'testcookie' => '1' ) ); $ch = curl_init( $base . '/wp-login.php' ); curl_setopt_array( $ch, array( CURLOPT_POST => true, CURLOPT_POSTFIELDS => $post, CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => false, CURLOPT_COOKIEFILE => '', CURLOPT_HEADER => true ) ); $raw = (string) curl_exec( $ch ); $code = (int) curl_getinfo( $ch, CURLINFO_HTTP_CODE ); curl_close( $ch ); preg_match_all( '/^Set-Cookie:\s*([^;\r\n]+).*$/mi', $raw, $matches ); $cookies = array(); foreach ( $matches[1] as $cookie ) { $cookies[] = $cookie; } return array( 'ok' => $code >= 200 && $code < 400 && (bool) preg_grep( '/^wordpress_logged_in_/', $cookies ), 'cookie' => implode( '; ', $cookies ), 'status' => $code ); }
function fetch_page( string $url, string $cookie ): array { $ch = curl_init( $url ); curl_setopt_array( $ch, array( CURLOPT_RETURNTRANSFER => true, CURLOPT_HEADER => true, CURLOPT_FOLLOWLOCATION => false, CURLOPT_COOKIE => $cookie ) ); $raw = (string) curl_exec( $ch ); $code = (int) curl_getinfo( $ch, CURLINFO_HTTP_CODE ); $header_size = (int) curl_getinfo( $ch, CURLINFO_HEADER_SIZE ); curl_close( $ch ); $headers = substr( $raw, 0, $header_size ); $body = substr( $raw, $header_size ); preg_match( '/^Cache-Control:\s*([^\r\n]+)/mi', $headers, $m ); return array( 'status' => $code, 'cache_control' => strtolower( trim( $m[1] ?? '' ) ), 'body' => $body, 'body_hash' => hash( 'sha256', $body ), 'body_bytes' => strlen( $body ) ); }
$observations = array(); $pages = array(); $ok = true; $logins = array();
foreach ( $users as $user ) { $login = login_cookie( $base, $user, $pass ); $logins[ $user ] = array( 'ok' => $login['ok'], 'status' => $login['status'] ); $ok = $ok && $login['ok']; foreach ( $urls as $url ) { $r = fetch_page( $base . $url, $login['cookie'] ); $r['user'] = $user; $r['url'] = $url; $pages[ $url ][ $user ] = $r['body']; unset( $r['body'] ); $observations[] = $r; $ok = $ok && ( false !== strpos( $r['cache_control'], 'private' ) || false !== strpos( $r['cache_control'], 'no-store' ) || in_array( $r['status'], array( 302, 401, 403 ), true ) ); } }
$leaks = array(); foreach ( $urls as $url ) { foreach ( $users as $owner ) { $other = $users[0] === $owner ? $users[1] : $users[0]; if ( false !== strpos( $pages[ $url ][ $other ], $owner ) ) { $leaks[] = array( 'url' => $url, 'owner' => $owner, 'viewer' => $other ); } } }
$ok = $ok && 10 === count( $observations ) && 0 === count( $leaks ); $out = array( 'objective' => 'SEC-CL-05', 'target' => '10 observations, private/no-store conforme, 0 fuite cross-user', 'logins' => $logins, 'observations' => $observations, 'cross_user_leaks' => $leaks, 'exit_code' => $ok ? 0 : 1, 'status' => $ok ? 'PASS' : 'FAIL', 'blocked_reason' => null ); file_put_contents( '/home/ubuntu/atelier-cdc-20/proofs-rc4-local/SEC-CL-05-private-cache.json', json_encode( $out, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE ) . PHP_EOL ); echo json_encode( $out, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE ) . PHP_EOL; exit( $out['exit_code'] );
